function UIActionSecondMapDialog:Awake()
    self.EventCONFIRMTIMETICK = Events.AddListener(Constants.EventNames.EVENT_CONFIRM_TIME_TICK, Bind(self, self.OnSaleOutTime))
    self.EventActionSecondMapJump = Events.AddListener(Constants.EventNames.ActionSecondMapJump, Bind(self, self.OnActionSecondMapJump))
    self.EventRegionLikability = Events.AddListener(Constants.EventNames.RegionLikability, Bind(self, self.OnRegionLikability))

    local quickSwipe = KTool.GetOrAddComponent(self.controller.gameObject, typeof(QuickSwipe))
    --quickSwipe.swipeDirection = 12 -- Horizontal ---只添加水平方向上的swipe的逻辑
    quickSwipe.onSwipeAction:AddListener(function(gesture)
        self:OnSwipeActionEvent(gesture)
    end)
    self._behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    self._behaviourAction.UpdateAction = function()
        self:OnFixUpdate()
    end
    if self.BtnAutoShowDrop then
        CfUtils.SetActive(self.BtnAutoShowDrop, false)
    end
    --SetButtonAction(self.BtnAutoShowDrop, Bind(self, self.OnBtnAutoShowDrop))
    SetButtonAction(self.Container.transform:Find("LvGroup"), Bind(self, self.OnBtnLvGroup))
    SetButtonAction(self.BtnShop, Bind(self, self.OnBtnShop))

end

function UIActionSecondMapDialog:OnBtnShop()
    local isUnlock, err = ActionUtils.IsUnlockStore(self._mapId)
    if not isUnlock then
        GameUtils.Toast(err)
        return
    end
    UIModule.OpenDialog({ id = Constants.UITypeIds.UIActionCityStoreDialog, parameters = { mapId = self._mapId, storeId = self._mapId } }, {
        { id = Constants.UITypeIds.UIActionSecondMapDialog }
    })
end

function UIActionSecondMapDialog:OnFixUpdate()
    self._idleTime = self._idleTime + CS.UnityEngine.Time.deltaTime
    if self._idleTime > 7 then
        self._idleTime = 0
        self:PlayStoreAni(StoreStatus.Type3)
    end

    if not self._inertiaMove then
        return
    end
    --self._curKeepTime = self._curKeepTime + CS.UnityEngine.Time.deltaTime
    --self._speed = self._speed * ((self._maxKeepTime - self._curKeepTime) / self._maxKeepTime)
    --if self._curKeepTime > self._maxKeepTime then
    --    self._inertiaMove = false
    --    return
    --end

    self._speed = self._speed * CS.System.Math.Pow(0.1, CS.UnityEngine.Time.deltaTime)
    local v3 = CS.UnityEngine.Vector3(self._speed.x, self._speed.y, 0)
    if math.abs(CS.UnityEngine.Vector3.Magnitude(v3)) < 1 then
        self._inertiaMove = false
        return
    end
    local deltaPos = self._speed * CS.UnityEngine.Time.deltaTime * 0.001
    local pos = self._mapCam.transform.position
    self:RefreshCamPos(Vector3(pos.x - deltaPos.x, pos.y - deltaPos.y, pos.z))
end

function UIActionSecondMapDialog:OnSwipeActionEvent(gesture)
    if gesture then
        if gesture.type == EasyTouch.EvtType.On_SwipeStart then
            self._inertiaMove = false

        elseif gesture.type == EasyTouch.EvtType.On_Swipe then
            local deltaPos = gesture.deltaPosition * 0.001
            local pos = self._mapCam.transform.position
            self:RefreshCamPos(Vector3(pos.x - deltaPos.x, pos.y - deltaPos.y, pos.z))
        elseif gesture.type == EasyTouch.EvtType.On_SwipeEnd then
            self._speed = gesture.deltaPosition / gesture.deltaTime
            self._maxKeepTime = 3   --持续时间
            self._curKeepTime = 0   --持续时间
            self._inertiaMove = true
        end
    end
end

function UIActionSecondMapDialog:RefreshCamPos(pos)
    if checkNumber(pos.x) < self._camMinX or checkNumber(pos.x) > self._camMaxX or checkNumber(pos.y) < self._camMinY or checkNumber(pos.y) > self._camMaxY then
        return
    end

    self._mapCam.transform.position = pos
    local urpBase = self._mapCam:GetComponent(typeof(URPBaseCamera))
    if not self.willClose then
        urpBase:CopyCamera()
    end

    self:RefreshPointPos()
end

function UIActionSecondMapDialog:RefreshPointPos()
    for k, v in pairs(self._allPoints) do
        local go = self.NodePar.transform:Find("go" .. v)
        local data = ActionUtils.GetRegionSecondaryMapVo(v)
        self:RefreshPos(go, data)
    end
end

