function UIActionSecondMapDialog:FillShop()
    local isUnlock, err = ActionUtils.IsUnlockStore(self._mapId)
    CfUtils.SetActive(self.BtnShop.transform:Find("ImgShop1/ImgLock"), not isUnlock)
    CfUtils.SetUISwitchImage(self.ImgShop2, isUnlock and 1 or 2)
    CfUtils.SetUISwitchImage(self.Imgbg6, isUnlock and 1 or 2)
    CfUtils.SetUISwitchImage(self.ImgShop1, isUnlock and 1 or 2)

    local vo = ActionUtils.GetRegionStoresVo(self._mapId)
    CfUtils.FillText(self.TxtSpinName, vo.name)
    local loader = ResourceModule.LoadBundleAsync(vo.resource, nil, true)
    while not loader.IsSuccess do
        cs_coroutine.yield_return()
    end
    if not loader.IsError then
        local parentTrans = self.MaskSpin.transform:Find("SpineScale").transform
        local go = loader:Instantiate(parentTrans)
        go.transform.localPosition = Vector3(0, 0, 0)
        go.transform.localScale = Vector3(1, 1, 1)
        self._spineGo = go.gameObject:GetComponent(typeof(SkeletonGraphic))
    end

    loader:Release()

    if self:IsRegionTaskUnlocked() then
        local go = GameUtils.GetRedPointGo(self.Container.transform:Find("LvGroup"))
        CfUtils.SetActive(go, ActionUtils.IsHasTaskCanDraw(self._mapId))
    else
        self:LockRegionTaskBtn()
    end
end

function UIActionSecondMapDialog:LockRegionTaskBtn()
    local imgIcon = self.Container.transform:Find("LvGroup/ImgIcon")
    if imgIcon then
        local SImg_Icon = imgIcon:GetComponent(typeof(CS.Game.Native.Common.UISwitchImage))
        if SImg_Icon then
            SImg_Icon.Status = 2
        end
    end
    local lock = self.Container.transform:Find("LvGroup/ImgIcon/ImgLock")
    if lock then
        KTool.SetActive(lock, true)
    end
    local childLvGroup = self.Container.transform:Find("LvGroup/Item/LvGroup")
    if childLvGroup then
        KTool.SetActive(childLvGroup, false)
    end
end

function UIActionSecondMapDialog:PlayStoreAni(aniType)
    if self._storeCo ~= nil then
        cs_coroutine.stop(self._storeCo)
        self._storeCo = nil
    end

    self._storeCo = cs_coroutine.start(function()
        if aniType == StoreStatus.Type4 then
            ---当进入二级地图时
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.3))
        end
        local t = ActionUtils.GetAllAnimaorIdByActionId(self._mapId, 1, aniType)
        if table.count(t) <= 0 then
            return
        end
        -- print(table.dump(t))
        local num = math.random(table.count(t))
        local id = t[num]

        local vo = ActionUtils.GetRegionStoreAnimatorVo(id)
        if not vo then
            return
        end
        CfUtils.FillText(self.TxtContent, vo.line)
        CfUtils.SetActive(self.ShopSpinTips, not string.isEmpty(checkString(vo.line)))

        CriWareUtils.PlayVoiceById(vo.soundEffects)
        -- print(vo.animation)

        local isLoop = (aniType == StoreStatus.Type1)
        CfUtils.PlaySpine(self._spineGo, vo.animation, isLoop)

        if aniType ~= StoreStatus.Type1 then
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(CfUtils.GetSpineTime(self._spineGo, vo.animation)))
            self:PlayStoreAni(StoreStatus.Type1)
        end
    end)
end

