        CfUtils.FillText(self.TxtNumber, num1 .. "/" .. num2)
    end
end

function UIActionSecondMapDialog:FillPoints(isInit)
    for k, v in pairs(self._allPoints) do
        local data = ActionUtils.GetRegionSecondaryMapVo(v)

        local node = self.LockNode
        if ActionUtils.IsUnlockRegionalSecondPoint(data.id) then
            node = self:GetNodeType(data.type)
        end

        if checkNumber(data.type) == Constants.RegionSecondMapPointType.Task then
            node = nil
        end

        if node then
            local go = self.NodePar.transform:Find("go" .. data.id)
            if not go then
                go = CfUtils.InstantiateGo(node.gameObject, self.NodePar)
                go.name = "go" .. data.id
            end
            self:FillPoint(go, data, isInit)
        end
    end
end

function UIActionSecondMapDialog:RefreshPos(go, data)
    if not go or not data then
        return
    end

    local targetGo = self._mapGo.transform:Find(data.id)
    if not targetGo then
        return
    end
    local tagetPos = targetGo.transform.position
    local pos = CfUtils.WorldPosition2UIPosition(tagetPos, self.NodePar, self._mapCam)
    go.transform.localPosition = Vector3(pos.x, pos.y, 0)  --ActionUtils.GetPos(data.id)
end

