--区域信息
---FillPoint
---@param go UnityEngine.GameObject
---@param data table
---@param isInit boolean
function UIActionSecondMapDialog:FillPoint(go, data, isInit)
    if not go or not data then
        return
    end

    --初始化的时候
    if isInit then
        --local t = CfUtils.Split(data.infoCoordinate)
        --t[1] = (data.id - 100) * 100 
        --t[2] = (data.id - 100) * 100 
        --go.transform.localPosition = Vector3(t[1], t[2], 0)
        self:RefreshPos(go, data)
        CfUtils.SetActive(go, true)

        local isUnlock = ActionUtils.IsUnlockRegionalSecondPoint(data.id)
        if isUnlock then
            if checkNumber(data.type) == Constants.RegionSecondMapPointType.Store then
                self:FillFishInfo(go, data)
            elseif checkNumber(data.type) == Constants.RegionSecondMapPointType.Boss then
                self:FillFishInfo(go, data)
                self:FillBossInfo(go, data)
            elseif checkNumber(data.type) == Constants.RegionSecondMapPointType.CommonBattle or
                    checkNumber(data.type) == Constants.RegionSecondMapPointType.ParticleBattle or
                    checkNumber(data.type) == Constants.RegionSecondMapPointType.ExpBattle then
                self:FillBattleInfo(go, data)
                if checkInt(data.type) == Constants.RegionSecondMapPointType.ExpBattle then
                    local isPassed = QuestConfMgr:GetInstance():IsPassQuest(BREAK_QUEST_ID)
                    if isPassed then
                        local planeGo = self._mapGo.transform:Find("AreaMap_01_0" .. self._mapId .. "_plane")
                        local greyGo = planeGo.transform:Find("GreyGroup/AreaMap_damage_" .. data.id)
                        CfUtils.SetActive(greyGo, isPassed)
                    end
                end
            elseif checkNumber(data.type) == Constants.RegionSecondMapPointType.Annihilation then
                --self:FillAnnihilationInfo(go, data)
                self:FillFishInfo(go, data)
                self:FillBossInfo(go, data)
            elseif checkNumber(data.type) == Constants.RegionSecondMapPointType.Fish then
                self:FillFishInfo(go, data)
                local redGo = GameUtils.GetRedPointGo(go)
                local num = redPointCom:GetNodeNum(Constants.RedPointConst["PhoneFishCollection" .. data.content])
                CfUtils.SetActive(redGo, num > 0)
            elseif checkNumber(data.type) == Constants.RegionSecondMapPointType.Sp then
                self:FillFishInfo(go, data)
            elseif checkNumber(data.type) == Constants.RegionSecondMapPointType.SaleOut then
                self:FillSaleOutInfo(go, data)
            elseif checkNumber(data.type) == Constants.RegionSecondMapPointType.WorldBoss then
                self:FillFishInfo(go, data)
            elseif checkNumber(data.type) == Constants.RegionSecondMapPointType.LadderPvp then
                self:FillFishInfo(go, data)
                ----pvp的节点处理
                if ActionUtils.IsLadderPvpUnlocked() and isUnlock then
                    ----pvp解锁了
                    local DestroyGroup = go.transform:Find("Root/DestroyGroup")
                    if DestroyGroup then
                        ---@type PlayerComponent
                        local playerComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
                        local serverTime = playerComponent.playerDojo:GetServerTime()
                        local startTime = AppService:GetInstance().ladderStartTimestamp
                        local finishTime = AppService:GetInstance().ladderEndTimestamp
                        local planeGo = self._mapGo.transform:Find("AreaMap_01_0" .. self._mapId .. "_plane")
                        local effectGo = planeGo.transform:Find("EffectGroup/Effect_" .. data.id)
                        if effectGo then
                            effectGo = effectGo:Find("CountDown")
                        end
                        local isInLadderOpenTime, ladderEndTime = AppService:GetInstance():IsInLadderOpenTime(serverTime)
                        if isInLadderOpenTime then
                            KTool.SetActive(DestroyGroup.gameObject, true)
                            CfUtils.SetActive(effectGo, true)
                            ---设置滚动条的相关逻辑
                            ---@type UIActionPromptUpItemNode
                            local upItemNode = AddLuaBehaviour(DestroyGroup.gameObject, 'Game.UI.FightReady.UIMainChapter.UIActionPromptUpItemNode')
                            if upItemNode then
                                if isNull(upItemNode.Env) then
                                    upItemNode:Init()
                                end
                                if upItemNode.Env then
                                    upItemNode.Env.MaskText = DestroyGroup:Find("MaskState")
                                    upItemNode.Env.TxtDesc = DestroyGroup:Find("MaskState/TxtTime")
                                    upItemNode.Env:AddListener()
                                    upItemNode.Env:Refresh(localize('天梯竞技场进行中...距离结束: _time_', { _time_ = second_toHHMMSS(checkNumber(ladderEndTime) - serverTime) }))
                                end
                            end
                        else
                            CfUtils.SetActive(effectGo, false)
                            KTool.SetActive(DestroyGroup.gameObject, false)
                        end
                    end
                end
            elseif checkNumber(data.type) == Constants.RegionSecondMapPointType.Pvp or checkNumber(data.type) == Constants.RegionSecondMapPointType.SinglePlayerPvp then
                self:FillFishInfo(go, data)
            end

            --local isOpen = ActionUtils.IsOpenAnnihilation(data.regionBelong)
            if checkNumber(data.type) == Constants.RegionSecondMapPointType.Annihilation then
                CfUtils.SetActive(go, true)
            elseif checkNumber(data.type) == Constants.RegionSecondMapPointType.Boss then
                CfUtils.SetActive(go, true)
            end

            local redGo = go.transform:Find("Root/NameGroup/ImgBg1/TxtName/ImgNew")
            CfUtils.SetActive(redGo, ActionUtils.IsShowRedpoint(data.id))
            redGo = go.transform:Find("Root/NameGroup/TxtName/ImgNew")
            CfUtils.SetActive(redGo, ActionUtils.IsShowRedpoint(data.id))
        else
            self:FillLockNode(go, data)
        end

        SetButtonAction(go.transform:Find("Root"), Bind(self, self.OnBtnPoint, data))

        local planeGo = self._mapGo.transform:Find("AreaMap_01_0" .. self._mapId .. "_plane")
        local greyGo = planeGo.transform:Find("GreyGroup/AreaMap_grey_" .. data.id)
        local effectGo = planeGo.transform:Find("EffectGroup/Effect_" .. data.id)
        CfUtils.SetActive(greyGo, not isUnlock)
        CfUtils.SetActive(effectGo, isUnlock)

        if checkNumber(data.type) == Constants.RegionSecondMapPointType.Boss then
            --local isOpen = ActionUtils.IsOpenAnnihilation(data.regionBelong)
            local isOpen = false
            if isOpen then
                CfUtils.SetActive(effectGo, false)
            end
        end

        local goodsParGo = go.transform:Find("Root/GoodList")
        CfUtils.SetActive(goodsParGo, false)
    else
        local goodsParGo = go.transform:Find("Root/GoodList")
        --if checkNumber(data.type) ~= Constants.RegionSecondMapPointType.Store then
        --    CfUtils.SetActive(goodsParGo, (self._isShowReward == 1))
        --end
        --
        --local t = checkTable(CfUtils.Split(data.reward))
        --if table.count(t) <= 0 or checkNumber(t[1]) == 0 then
            CfUtils.SetActive(goodsParGo, false)
        --end
    end
end

