function UIActionSecondMapDialog:FillSaleOutInfo(go, data)
    local rootGo = go.transform:Find("Root")

    local positionId = checkNumber(data.id)
    ---@type RegionSecondaryMapVo
    local vo = ActionUtils.GetRegionSecondaryMapVo(positionId)
    ---订单数据
    local dojo = maidCoffeePlayerComponent:GetTakeoutOrdersByAreaId(vo.regionBelong, positionId)
    KTool.SetActive(go, dojo ~= nil)
    if dojo then
        CfUtils.SetActive(rootGo.transform:Find("NPChead"), checkNumber(dojo.status) == 0)
        CfUtils.SetActive(rootGo.transform:Find("ImgFinishBag"), checkNumber(dojo.status) == 2)
        CfUtils.SetActive(rootGo.transform:Find("Dispatching"), checkNumber(dojo.status) == 1)
        ---@type MaidCoffeeTakeOutOrderNpcVo
        local npcVo = CfUtils.GetCfVo(AutoIds.IdSetting3055, "MaidCoffeeTakeOutOrderNpcVo", dojo.npcId)
        if npcVo then
            CfUtils.FillImage(rootGo.transform:Find("NPChead/ImgNpcHead"), npcVo.icon)
        end
    end
    self:FillSaleOutTime(go, data)
end

function UIActionSecondMapDialog:FillSaleOutTime(go, data)
    local positionId = checkNumber(data.id)
    local dojo = maidCoffeePlayerComponent:GetTakeoutOrdersByAreaId(self._mapId, positionId)
    if not dojo then
        return
    end
    local rootGo = go.transform:Find("Root")
    local time = checkNumber(dojo.remainTime)
    CfUtils.FillText(rootGo.transform:Find("Dispatching/TxtTime"), CfUtils.GetTimeHMS(time))
end

function UIActionSecondMapDialog:FillBossInfo(go, data)
    local rootGo = go.transform:Find("Root")

    local destroyGroupGo = rootGo.transform:Find("DestroyGroup")
    CfUtils.SetActive(destroyGroupGo, false)

    CfUtils.SetActive(destroyGroupGo.transform:Find("MaskState"), false)
    CfUtils.SetActive(destroyGroupGo.transform:Find("TimeGroup"), false)
    CfUtils.SetActive(destroyGroupGo.transform:Find("ProgressGroup"), true)

    local isFinish = false
    CfUtils.SetActive(destroyGroupGo.transform:Find("ProgressGroup/Finish"), isFinish)
    CfUtils.SetActive(destroyGroupGo.transform:Find("ProgressGroup/Normal"), not isFinish)
    if not isFinish then
        local img = destroyGroupGo.transform:Find("ProgressGroup/Normal/Img2").transform:GetComponent(typeof(CS.UnityEngine.UI.Image))
        local data = ActionUtils.GetAnnihilationInfo(self._mapId)
        img.fillAmount = checkNumber(data.progress)
        CfUtils.FillText(destroyGroupGo.transform:Find("ProgressGroup/Normal/TxtProgress"), localize("_num1_<size=30>%</size>", { _num1_ = checkInt(checkNumber(data.progress) * 100) }))
    else

    end
end


--普通战斗
