--点击区域点
function UIActionSecondMapDialog:OnBtnPoint(data)
    if not data then
        return
    end

    local isUnlock, err = ActionUtils.IsUnlockRegionalSecondPoint(data.id)
    if not isUnlock then
        GameUtils.Toast(err)
        return
    end
    if checkNumber(data.type) == Constants.RegionSecondMapPointType.Fish then
        local FishingUtils = import('Game.UI.Fishing.FishingUtils')
        local isUnlock, err = FishingUtils.IsUnlockFishPlace(data.content)
        if not isUnlock then
            GameUtils.Toast(err)
            return
        end
    end
    ActionUtils.RemoveRedPointIds(data.id)

    KCookie.Set("UIActionSecondMapDialogEntry", 1)

    RegionQuestMgr:GetInstance():PlaySecondMapAnimation(data.id)
    CfUtils.SetTopActive(false)
    CfUtils.SetActive(self.controller.gameObject, false)
    --这个时候不能惯性移动了
    self._inertiaMove = false

    self._openCo = cs_coroutine.start(function()
        self:PlayStoreAni(StoreStatus.Type2)

        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.2))
        CfUtils.SetTopActive(true)

        local regionType = checkInt(data.type)
        if (regionType == Constants.RegionSecondMapPointType.Boss or
            regionType == Constants.RegionSecondMapPointType.CommonBattle or
            regionType == Constants.RegionSecondMapPointType.ParticleBattle or
            regionType == Constants.RegionSecondMapPointType.ExpBattle) then
            self._isKeepSceneGo = true
            CoYield(CfUtils.DialogOpen(Constants.UITypeIds.UIActionPointMapDialog, { id = data.id, targetQuestId = self._targetQuestId, isFromEntry = self._isFromEntry }, {
                UIArgs(Constants.UITypeIds.UIActionSecondMapDialog)
            }))

        -- 歼灭战
        elseif regionType == Constants.RegionSecondMapPointType.Annihilation then
            self._isKeepSceneGo = false
            CoYield(CfUtils.DialogOpen(Constants.UITypeIds.ActionPointMapBossDialog, { isFromEntry = self._isFromEntry }, {
                UIArgs(Constants.UITypeIds.UIActionSecondMapDialog)
            }))

        -- 商店
        elseif regionType == Constants.RegionSecondMapPointType.Store then
            self._isKeepSceneGo = true
            CfUtils.DialogOpen(Constants.UITypeIds.UIActionCityStoreDialog, { mapId = self._mapId, storeId = data.content, isFromEntry = self._isFromEntry }, {
                UIArgs(Constants.UITypeIds.UIActionSecondMapDialog)
            })

        -- SP材料
        elseif regionType == Constants.RegionSecondMapPointType.Sp then
            self._isKeepSceneGo = true
            KCookie.Set("UIActionSPMapDialogEntry", 1)
            CoYield(CfUtils.DialogOpen(Constants.UITypeIds.UIActionSPMapDialog, { id = data.id, isFromEntry = self._isFromEntry }, {
                UIArgs(Constants.UITypeIds.UIActionSecondMapDialog)
            }))

        -- 渔场
        elseif regionType == Constants.RegionSecondMapPointType.Fish then
            ---@type FishingComponent
            local fishingComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.FishingComponent)
            fishingComponent:FishingHomeReq(function()
                CfUtils.SetActive(self._mapCam, false)
                ---@type FishingMgr
                local FishingMgr = import('Game.UI.Fishing.FishingMgr')
                FishingMgr:GetInstance():EnranceFishPlace(data.content, self._goodsVo)
                RegionQuestMgr:GetInstance():ClearCurMapGo()
            end)

        -- 世界boss
        elseif regionType == Constants.RegionSecondMapPointType.WorldBoss then
            ---@type WorldBossComponent
            local worldBossComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.WorldBossComponent)
            worldBossComponent:OnWorldBossEnter()

        -- 外卖
        elseif regionType == Constants.RegionSecondMapPointType.SaleOut then
            self._isKeepSceneGo = true
            local positionId = checkNumber(data.id)
            ---@type RegionSecondaryMapVo
            local vo = ActionUtils.GetRegionSecondaryMapVo(positionId)
            ---@type MaidCoffeePlayerComponent
            local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
            ---订单数据
            local dojo = maidCoffeePlayerComponent:GetTakeoutOrdersByAreaId(vo.regionBelong, positionId)
            CoYield(CfUtils.DialogOpen(Constants.UITypeIds.UIMaidCoffeeTakeoutPopupDialog, dojo, {
                UIArgs(Constants.UITypeIds.UIActionSecondMapDialog)
            }))

        -- 即时PVP
        elseif regionType == Constants.RegionSecondMapPointType.LadderPvp then
            CoYield(CfUtils.DialogOpen(Constants.UITypeIds.LadderCompetionMainDialog, nil, {
                UIArgs(Constants.UITypeIds.UIActionSecondMapDialog)
            }))

        -- 单人PVP
        elseif regionType == Constants.RegionSecondMapPointType.SinglePlayerPvp then
          CoYield(CfUtils.DialogOpen(Constants.UITypeIds.LadderStruggleSingleMainDialog, { systemName = Constants.SystemToggleIds.Id2017 }, {
            UIArgs(Constants.UITypeIds.UIActionSecondMapDialog)
        }))

        -- 异步PVP
        elseif regionType == Constants.RegionSecondMapPointType.Pvp then
            CoYield(CfUtils.DialogOpen(Constants.UITypeIds.LadderStruggleMainDialog, { systemName = Constants.SystemToggleIds.Id2007 }, {
                UIArgs(Constants.UITypeIds.UIActionSecondMapDialog)
            }))
        end

    end)
end

