--获取类型对应的点
function UIActionSecondMapDialog:GetNodeType(type)
    type = checkNumber(type)
    if type == Constants.RegionSecondMapPointType.Store then
        print("!!!!!!!!!!!!!!!!!!")
        return nil --self.ProjectNode
    elseif type == Constants.RegionSecondMapPointType.Boss then
        return self.ProjectNode
    elseif type == Constants.RegionSecondMapPointType.CommonBattle or
            type == Constants.RegionSecondMapPointType.ParticleBattle or
            type == Constants.RegionSecondMapPointType.ExpBattle then
        return self.PositionNode
    elseif type == Constants.RegionSecondMapPointType.Annihilation then
        return self.ProjectNode
    elseif type == Constants.RegionSecondMapPointType.Fish then
        return self.FishNode
    elseif type == Constants.RegionSecondMapPointType.Sp then
        return self.ProjectNode
    elseif type == Constants.RegionSecondMapPointType.Pvp then
        return self.ProjectNode
    elseif type == Constants.RegionSecondMapPointType.LadderPvp or type == Constants.RegionSecondMapPointType.SinglePlayerPvp then
        return self.ProjectNode
    elseif type == Constants.RegionSecondMapPointType.WorldBoss then
        return self.ProjectNode
    elseif type == Constants.RegionSecondMapPointType.SaleOut then
        local isUnlock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id3003)
        if not isUnlock then
            return nil
        end
        return self.SaleOutNode
    end
    return nil
end

function UIActionSecondMapDialog:OnCaptureAction()
    self.willClose = true
end

function UIActionSecondMapDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        CfUtils.SetUICameraProjection(true)

        KTool.SetRenderFeatureActiveByName(Constants.RenderFeatureNames.BLUR, false)

        local lastPos, lastClickId = RegionQuestMgr:GetInstance():GetLastCamPos()
        if lastPos and self._isFromEntry then
            CoStart(function()
                CoYield()
                CfUtils.DialogBack()
            end)
            return
        end

        self._co = cs_coroutine.start(function()
            CS.Engine.UI.UIRaycastBlocker.Instance:AddCondition("UIActionSecondMapDialogAnimation")
            CfUtils.SetActive(self.Root, false)
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.2))
            CfUtils.SetActive(self.Root, true)
            CfUtils.SetActive(self._mapCam, true)

            local urpBase = self._mapCam:GetComponent(typeof(URPBaseCamera))
            local vo = ActionUtils.GetRegionPrimaryMapVo(self._mapId)
            if lastPos then
                CfUtils.SetTopActive(false)
                CfUtils.SetActive(self.Root, false)
                local fPos = Vector3(0, 0, 0)
                local targetGo = self._mapGo.transform:Find("CameraEndPos_" .. lastClickId)
                if targetGo then
                    fPos = targetGo.transform.position
                end
                local tPos = lastPos
                CfUtils.DoTween(1, function(updateValue)
                    self._mapCam.transform.position = CS.UnityEngine.Vector3.Lerp(fPos, tPos, updateValue)
                    self:RefreshPointPos()
                    if not self.willClose then
                        urpBase:CopyCamera()
                    end
                end, function()

                end)
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.1))
                CfUtils.SetTopActive(true)
                CfUtils.SetActive(self.Root, true)
            else
                local position = RegionQuestMgr:GetInstance():GetSecondMapOriginCameraPos()
                if position then
                    print('====>> 当前的位置', position)
                    --local t = CfUtils.Split(vo.enterCameraPos)
                    self._mapCam.transform.position = position
                    if not self.willClose then
                        urpBase:CopyCamera()
                    end
                end
            end

            local t = nil
            t = CfUtils.Split(vo.cameraPosX)
            self._camMinX = checkNumber(t[1])
            self._camMaxX = checkNumber(t[2])
            t = CfUtils.Split(vo.cameraPosY)
            self._camMinY = checkNumber(t[1])
            self._camMaxY = checkNumber(t[2])

            --CfUtils.PlayAnimator(self.BtnAutoShowDrop.transform:Find("AnimRoot"), self._isShowReward == 1 and "ON" or "OFF")

            --ActionUtils.HandleMainQuestPass(10103)
            --这里播解锁动画
            t = ActionUtils.GetUnlockPointIds()
            if table.count(t) > 0 then
                self._unLockEffectLoader = ResourceModule.LoadBundleAsync("Arts/Prefab/MainQuestMap/Prefab/AreaMap_Effect_Unlock.prefab", nil, true)
                while not self._unLockEffectLoader.IsSuccess do
                    cs_coroutine.yield_return(Yielders.EndOfFrame)
                end
                if self._unLockEffectLoader.IsError then
                    self._unLockEffectLoader:Release(true)
                else
                    if not self._unLockEffectLoader.ResultObject then
                        self._unLockEffectLoader:Release(true)
                    else
                        for k, v in pairs(t) do
                            --local planeGo = self._mapGo.transform:Find("AreaMap_01_0"..self._mapId.."_plane")
                            local go = self._mapGo.transform:Find(v)
                            if not isNull(go) then
                                local camTargetGo = self._mapGo.transform:Find("CameraEndPos_" .. v)
                                local fPos = self._mapCam.transform.position

                                local pointVo = ActionUtils.GetRegionSecondaryMapVo(v)
                                t = checkTable(CfUtils.Split(pointVo.camera))
                                local x = checkNumber(t[1])
                                local y = checkNumber(t[2])
                                local tPos = Vector3(x, y, fPos.z)
                                --urpBase:CopyCamera()
                                --CfUtils.DoTween(0.5, function(updateValue)
                                --    self._mapCam.transform.position = CS.UnityEngine.Vector3.Lerp(fPos, tPos, updateValue)
                                --    if not self.willClose then
                                --        urpBase:CopyCamera()
                                --    end
                                --end, function()
                                --
                                --end)
                                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.5))
                                local unlockGo = CfUtils.InstantiateGo(self._unLockEffectLoader.ResultObject, go)
                                CfUtils.SetActive(unlockGo, true)
                                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.2))
                            end
                        end

                    end
                end

                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1))
            end

            local bossShow = checkNumber(CS.Engine.Lib.KCookie.Get("RegionalBossNewUnlock"))
            local targetPointId = checkNumber(KCookie.Get("UIActionSecondMapDialogtargetPointId"))
            --歼灭战解锁了 播放动画
            if bossShow > 0 then
                CS.Engine.Lib.KCookie.Set("RegionalBossNewUnlock", 0)

                local bossGo = RegionQuestMgr:GetInstance():GetBossGo()
                CfUtils.SetActive(bossGo, true)

                if not isNull(bossGo) then
                    CfUtils.PlayAnimator(bossGo, "enter")
                end
                local bossPointId = ActionUtils.GetBossPointId(self._mapId)
                local effectGo = self._mapGo.transform:Find(bossPointId .. "/Effect_" .. bossPointId)
                if effectGo then
                    CfUtils.SetActive(effectGo.transform:Find("AreaMap_Effect_Tareats"), true)
                    CfUtils.SetActive(effectGo, true)
                    CfUtils.PlayAnimation(effectGo.transform:Find("AreaMap_Effect_Tareats"), "AreaMap_Effect_Tareats_Entry")
                    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.5))
                    CfUtils.PlayAnimation(effectGo.transform:Find("AreaMap_Effect_Tareats"), "AreaMap_Effect_Tareats_Loop")
                end
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1.5))
                CfUtils.SetActive(self.UIFX_Thkeats, true)

                self:RefreshPointPos()
            end

            --有目标点
            if targetPointId > 0 then
                KCookie.Set("UIActionSecondMapDialogtargetPointId", 0)
                local vo = ActionUtils.GetRegionSecondaryMapVo(targetPointId)
                if checkNumber(vo.type) == Constants.RegionSecondMapPointType.Boss then
                    --local isOpen = ActionUtils.IsOpenAnnihilation(self._mapId)
                    --if isOpen then
                    targetPointId = ActionUtils.GetBossRegionPointId(self._mapId)
                    --end
                end

                self:RefreshPointPos()
                CfUtils.SetActive(self.NodePar, true)

                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.5))
                local data = ActionUtils.GetRegionSecondaryMapVo(targetPointId)
                CfUtils.SetActive(self._mapGo.transform:Find("AreaMap_01_0" .. self._mapId .. "_plane/EffectGroup"), true)

                CfUtils.SetActive(RegionQuestMgr:GetInstance()._bossGo, true)
                CS.Engine.UI.UIRaycastBlocker.Instance:RemoveCondition("UIActionSecondMapDialogAnimation")
                self:OnBtnPoint(data)
            else
                self:RefreshPointPos()
                CfUtils.SetActive(self.NodePar, true)
                --local isOpen = ActionUtils.IsOpenAnnihilation(self._mapId)
                local isOpen = false
                CfUtils.SetActive(self.UIFX_Thkeats, isOpen)
                local bossPointId = ActionUtils.GetBossPointId(self._mapId)
                local effectGo = self._mapGo.transform:Find(bossPointId .. "/Effect_" .. bossPointId)
                if effectGo then
                    CfUtils.SetActive(effectGo.transform:Find("AreaMap_Effect_Tareats"), isOpen)
                    CfUtils.SetActive(effectGo, isOpen)
                    CfUtils.PlayAnimation(effectGo.transform:Find("AreaMap_Effect_Tareats"), "AreaMap_Effect_Tareats_Loop")
                end
                CfUtils.SetActive(self._mapGo.transform:Find("AreaMap_01_0" .. self._mapId .. "_plane/EffectGroup"), true)
                if lastPos then
                    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.55))
                end
                CfUtils.SetActive(RegionQuestMgr:GetInstance()._bossGo, true)
                CS.Engine.UI.UIRaycastBlocker.Instance:RemoveCondition("UIActionSecondMapDialogAnimation")
                local isOpen = true
                if isOpen then
                    self:PlayStoreAni(StoreStatus.Type4)
                else
                    self:PlayStoreAni(StoreStatus.Type2)
                end
            end
        end)
    end))
    return coWait
end

