--收到事件跳转
function UIActionSecondMapDialog:OnActionSecondMapJump()
    local targetPointId = checkNumber(KCookie.Get("UIActionSecondMapDialogtargetPointId"))
    if targetPointId > 0 then
        local vo = ActionUtils.GetRegionSecondaryMapVo(targetPointId)
        if checkNumber(vo.regionBelong) ~= checkNumber(self._mapId) then
            RegionQuestMgr:GetInstance():SpecialJump(targetPointId)
            KCookie.Set("UIActionSecondMapDialogtargetPointId", 0)
        else
            local data = ActionUtils.GetRegionSecondaryMapVo(targetPointId)
            self:OnBtnPoint(data)
            KCookie.Set("UIActionSecondMapDialogtargetPointId", 0)
        end
    end
end

function UIActionSecondMapDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        CfUtils.SetTopActive(true)
        local argument = self.controller.Argument.parameters
        if not argument then
            return
        end
        self._mapId = checkNumber(argument.id)
        self._targetQuestId = checkNumber(argument.targetQuestId)    --跳转时候的默认id
        self._goodsVo = argument.goodsVo
        self._mapGo = RegionQuestMgr:GetInstance():GetCurMapGo(self._mapId)
        self._mapCam = self._mapGo.transform:Find("AreaMap_01_01_Camera").gameObject:GetComponent(typeof(Camera))
        self._isFromEntry = checkBool(argument.isFromEntry)
        local bgFx = self._mapGo.transform:Find("BG_FX")
        CfUtils.SetActive(bgFx, true)
        self:InitData()
        self:FillSelf()
        self:FillShop()

        --CfUtils.SetActive(self._mapGo.transform:Find("AreaMap_01_0" .. self._mapId .. "_plane/EffectGroup"), false)
        CfUtils.SetActive(self.NodePar, false)
    end))
    return coWait
end

function UIActionSecondMapDialog:OnFocus(focus)
    if focus then
        self._isKeepSceneGo = false
    end
end

function UIActionSecondMapDialog:OnHide()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self._behaviourAction.UpdateAction = nil
        CfUtils.SetActive(self.Root, false)
        if not isNull(self._mapGo) then
            CfUtils.SetActive(self._mapGo.transform:Find("AreaMap_01_0" .. self._mapId .. "_plane/EffectGroup"), false)

            local parGo = self._mapGo.transform:Find("ParticleSystem")
            CfUtils.SetActive(parGo, false)
        end
    end))
    return coWait
end

function UIActionSecondMapDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        ActionUtils.SaveRedPointData()
        self._behaviourAction.UpdateAction = nil
        Events.RemoveListener(Constants.EventNames.EVENT_CONFIRM_TIME_TICK, self.EventCONFIRMTIMETICK)
        Events.RemoveListener(Constants.EventNames.ActionSecondMapJump, self.EventActionSecondMapJump)
        Events.RemoveListener(Constants.EventNames.RegionLikability, self.EventRegionLikability)
        if not self._isKeepSceneGo then
            RegionQuestMgr:GetInstance():ClearCurMapGo()
        end

        if self._storeCo ~= nil then
            cs_coroutine.stop(self._storeCo)
            self._storeCo = nil
        end

        if self._co ~= nil then
            cs_coroutine.stop(self._co)
            self._co = nil
        end

        if self._openCo ~= nil then
            cs_coroutine.stop(self._openCo)
            self._openCo = nil
        end

        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIActionSecondMapDialog
